content:
此外掛程式可讓您為 [Ars Nouveau](https://www.curseforge.com/minecraft/mc-mods/ars-nouveau) 模組建立配方。

注意：Modrinth 並未託管 Ars Nouveau 模組，因此若要執行此模組，您必須從其他來源安裝它。

```js
ServerEvents.recipes(event => {
	event.recipes.ars_nouveau.enchanting_apparatus(
        [
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
        ], // 輸入物品
	    "minecraft:gunpowder", // 觸媒
	    "minecraft:tnt", // 輸出
	    1000, // 源力消耗
	    // true // 保留觸媒的 NBT，概念類似鍛造配方
	);

	event.recipes.ars_nouveau.enchantment(
        [
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
            "minecraft:sand",
        ], // 輸入物品
        "minecraft:vanishing_curse", // 套用附魔
        1, // 附魔等級
        1000, // 源力消耗
    );

	event.recipes.ars_nouveau.crush(
        "minecraft:tnt", // 輸入方塊
        [{
            item: "minecraft:sand",
            chance: 1
        }] // 戰利品表
        // true // 是否在世界中掉落物品？
    );

    /*
    // 這*確實*有效，但配方必須是書冊中的有效符文
    // 因此這實際上僅能用於
    // 替換現有符文的配方
    event.recipes.ars_nouveau.glyph(
        "minecraft:tnt", // 輸出物品（符文）
        [
            "minecraft:sand", 
            "minecraft:gunpowder",
        ], // 輸入物品
        3 // 經驗消耗
    );
    */

    // 可透過 `/ars-tome id` 指令存取，此例為 `/ars-tome kubejs:not_glow`
  	// 此為直接複製基礎 Ars Nouveau 中的「發光陷阱」書冊
    event.recipes.ars_nouveau.caster_tome(
        "Not-Glow Trap", // 名稱，
        [
            "ars_nouveau:glyph_touch",
            "ars_nouveau:glyph_rune",
            "ars_nouveau:glyph_snare",
            "ars_nouveau:glyph_extend_time",
            "ars_nouveau:glyph_light"
        ], // 法術
        "不會困住目標並賦予其他目標發光效果。", // 描述
        16718260, // 顏色
        {
            "family": "ars_nouveau:default",
            "pitch": 1.0,
            "volume": 1.0
        },
    ).id("kubejs:not_glow")

    event.recipes.ars_nouveau.imbuement(
        "minecraft:sand", // 輸入物品
        "minecraft:tnt", // 輸出
        1000, // 源力消耗
        [
            "minecraft:gunpowder" 
        ] // 祭壇物品 // 選填
    )
})
```
